{"function": "() => {
    const main = document.getElementById('elm-main-content');
    if (!main) return 'No main';
    // Get all text nodes within main, but exclude script, style, noscript, etc.
    const walker = document.createTreeWalker(main, NodeFilter.SHOW_TEXT, {
        acceptNode: function(node) {
            // Skip text inside script, style, etc.
            if (node.parentNode.nodeName === 'SCRIPT' || node.parentNode.nodeName === 'STYLE' || node.parentNode.nodeName === 'NOSCRIPT') {
                return NodeFilter.FILTER_REJECT;
            }
            // Skip empty text nodes
            if (!node.textContent.trim()) return NodeFilter.FILTER_REJECT;
            return NodeFilter.FILTER_ACCEPT;
        }
    });
    let text = '';
    let node;
    while (node = walker.nextNode()) {
        text += node.textContent + ' ';
    }
    return text.replace(/\s+/g, ' ').trim();
}"}

